P_COLOR_PRIMARY:"#22DE7A",REACT_APP_COLOR_PRIMARY_DARK:"#12B45F",REACT_APP_COLOR_SECONDARY:"#38BDF8",REACT_APP_COLOR_SURFACE:"#0F2233",REACT_APP_COLOR_TEXT:"#F2F7FA",REACT_APP_COLOR_TEXT_MUTED:"#93AABD",REACT_APP_COMPANY_LEGAL_NAME:"ReservaBot",REACT_APP_COMPANY_NAME:"ReservaBot",REACT_APP_CTA_FINAL_BUTTON:"Quiero mi mes gratis",REACT_APP_CTA_FINAL_SUBTITLE:"Tu recepcionista digital ya est\xe1 lista. Empieza hoy con 30 d\xedas gratis, sin tarjeta y sin compromiso.",REACT_APP_CTA_FINAL_TITLE:"\xbfListo para dejar de perder citas?",REACT_APP_CTA_NAV_LABEL:"Prueba 1 mes gratis",REACT_APP_CTA_PRIMARY_LABEL:"Pide tu DEMO GRATIS",REACT_APP_CTA_SECONDARY_LABEL:"Ver la app en acci\xf3n",REACT_APP_CURRENCY_CODE:"COP",REACT_APP_CURRENCY_SYMBOL:"",REACT_APP_CURRENCY_THOUSANDS:".",REACT_APP_DEFAULT_VERTICAL:"barber",REACT_APP_DEMOS_CTA_LABEL:"Pide el link del demo",REACT_APP_DEMOS_CTA_NOTE:"Te pasamos el link del chatbot por WhatsApp para que agendes una cita de prueba t\xfa mismo.",REACT_APP_DEMOS_EYEBROW:"M\xedralo funcionando",REACT_APP_DEMOS_SUBTITLE:"As\xed se ve ReservaBot para tus clientes, para ti y para tu equipo. Elige tu tipo de negocio y dale play.",REACT_APP_DEMOS_TITLE:"Una sola app, tres experiencias",REACT_APP_EMAIL:"johandarioalarcon@gmail.com",REACT_APP_FACEBOOK_URL:"https://www.facebook.com/profile.php?id=61593143103170",REACT_APP_FAQ_1_A:"S\xed. Activas tu cuenta, usas ReservaBot 30 d\xedas completos con todas las funciones y no pagas nada. No pedimos tarjeta de cr\xe9dito y si no te convence, simplemente no contin\xfaas.",REACT_APP_FAQ_1_Q:"\xbfDe verdad el primer mes es gratis?",REACT_APP_FAQ_2_A:".000 al mes, precio \xfanico. Incluye el chatbot, el panel de administrador y la app para todo tu equipo, sin importar cu\xe1ntas personas trabajen contigo. Sin contratos: te retiras cuando quieras.",REACT_APP_FAQ_2_Q:"\xbfCu\xe1nto cuesta despu\xe9s del mes gratis?",REACT_APP_FAQ_3_A:"No. Es una app web (PWA): tus clientes abren tu link desde el navegador del celular y el chatbot los gu\xeda para agendar. T\xfa y tu equipo tampoco instalan nada.",REACT_APP_FAQ_3_Q:"\xbfMis clientes tienen que descargar una app?",REACT_APP_FAQ_4_A:"S\xed. Es el mismo sistema configurado distinto: en barber\xeda con turnos cortos por barbero; en u\xf1as con servicios de mayor duraci\xf3n y su propia agenda. En esta p\xe1gina puedes ver los videos de cada uno.",REACT_APP_FAQ_4_Q:"\xbfSirve igual para barber\xeda y para sal\xf3n de u\xf1as?",REACT_APP_FAQ_5_A:"Escr\xedbenos por WhatsApp y te pasamos el link del chatbot de demostraci\xf3n para que agendes una cita de prueba t\xfa mismo. Si te gusta, te creamos tu cuenta y te damos acceso al panel de administrador.",REACT_APP_FAQ_5_Q:"\xbfC\xf3mo veo el demo?",REACT_APP_FAQ_6_A:"Normalmente el mismo d\xeda. Nosotros cargamos tus servicios, precios y tu equipo por ti, y te acompa\xf1amos en la primera configuraci\xf3n por WhatsApp.",REACT_APP_FAQ_6_Q:"\xbfCu\xe1nto me demoro en tenerlo listo?",REACT_APP_FAQ_7_A:"",REACT_APP_FAQ_7_Q:"",REACT_APP_FAQ_8_A:"",REACT_APP_FAQ_8_Q:"",REACT_APP_FAQ_EYEBROW:"Resolvamos dudas",REACT_APP_FAQ_TITLE:"Preguntas frecuentes",REACT_APP_FEATURES_EYEBROW:"Todo incluido",REACT_APP_FEATURES_SUBTITLE:"Reservas, recordatorios, caja y reportes en una sola herramienta.",REACT_APP_FEATURES_TITLE:"La recepcionista que nunca duerme",REACT_APP_FEATURE_1_ICON:"bot",REACT_APP_FEATURE_1_TEXT:"Tus clientes abren tu link, conversan con el bot y agendan en menos de 2 minutos. De d\xeda, de noche y en festivos.",REACT_APP_FEATURE_1_TITLE:"Chatbot que reserva solo",REACT_APP_FEATURE_2_ICON:"bell",REACT_APP_FEATURE_2_TEXT:"Cada cita queda confirmada al instante y el cliente recibe su recordatorio autom\xe1tico en la app. Menos plantones.",REACT_APP_FEATURE_2_TITLE:"Confirma y recuerda por ti",REACT_APP_FEATURE_3_ICON:"calendar",REACT_APP_FEATURE_3_TEXT:"Cada barbero o manicurista con su horario, sus servicios y sus descansos. Sin cruces ni dobles reservas.",REACT_APP_FEATURE_3_TITLE:"Agenda por profesional",REACT_APP_FEATURE_4_ICON:"money",REACT_APP_FEATURE_4_TEXT:"Registra ventas en efectivo, tarjeta y transferencia. La comisi\xf3n de cada profesional se calcula sola.",REACT_APP_FEATURE_4_TITLE:"",REACT_APP_FEATURE_5_ICON:"chart",REACT_APP_FEATURE_5_TEXT:"Cu\xe1nto vendiste hoy, tus horas pico y tus servicios m\xe1s rentables. Decisiones con n\xfameros, no con corazonadas.",REACT_APP_FEATURE_5_TITLE:"Reportes que s\xed entiendes",REACT_APP_FEATURE_6_ICON:"phone",REACT_APP_FEATURE_6_TEXT:"Es una app web (PWA): t\xfa y tus clientes entran desde el navegador de cualquier celular. Siempre actualizada.",REACT_APP_FEATURE_6_TITLE:"Sin descargar nada",REACT_APP_FEATURE_7_ICON:"",REACT_APP_FEATURE_7_TEXT:"",REACT_APP_FEATURE_7_TITLE:"",REACT_APP_FEATURE_8_ICON:"",REACT_APP_FEATURE_8_TEXT:"",REACT_APP_FEATURE_8_TITLE:"",REACT_APP_FONT_BODY:"Inter",REACT_APP_FONT_HEADING:"Montserrat",REACT_APP_FOOTER_ABOUT:"ReservaBot es la recepcionista digital de barber\xedas y salones de u\xf1as: un chatbot inteligente que agenda, confirma y recuerda las citas por ti, con panel de administraci\xf3n y app para tu equipo.",REACT_APP_FOOTER_COPYRIGHT:"Todos los derechos reservados.",REACT_APP_FOOTER_LINKS_LEGAL:"Pol\xedtica de privacidad::#|T\xe9rminos y condiciones::#",REACT_APP_FOOTER_LINKS_PRODUCT:"La app::#demos|Funciones::#features|Precio::#pricing|Preguntas::#faq",REACT_APP_FREE_TRIAL_BADGE:"Primer mes GRATIS",REACT_APP_FREE_TRIAL_DAYS:"30",REACT_APP_FREE_TRIAL_ENABLED:"true",REACT_APP_FREE_TRIAL_NOTE:"Oferta para nuevos negocios. Cupos limitados por mes.",REACT_APP_HERO_BULLETS:"Tus clientes reservan solos en la app|Confirma y recuerda cada cita|Menos plantones, m\xe1s ingresos",REACT_APP_HERO_CHAT_1:"in::Hola \ud83d\udc4b Quiero manicure hoy",REACT_APP_HERO_CHAT_2:"out::\xa1Claro! Tengo 3:00 pm y 5:30 pm \u2728",REACT_APP_HERO_CHAT_3:"in::3:00 pm",REACT_APP_HERO_CHAT_4:"out::\u2705 Cita confirmada\\nHoy 3:00 pm \xb7 Manicure",REACT_APP_HERO_CHAT_5:"out::Te recordar\xe9 2 h antes \u23f0",REACT_APP_HERO_CHAT_6:"in::\xa1Gracias! \ud83d\ude4c",REACT_APP_HERO_CHAT_7:"",REACT_APP_HERO_CHAT_8:"",REACT_APP_HERO_CHAT_HEADER:"ReservaBot",REACT_APP_HERO_CHAT_STATUS:"en l\xednea",REACT_APP_HERO_EYEBROW:"Barber\xedas & salones de u\xf1as",REACT_APP_HERO_FLOAT_1:"Nueva reserva::Andr\xe9s \xb7 Corte + barba \xb7 3:30 pm",REACT_APP_HERO_FLOAT_2:"Recordatorio enviado::12 clientas notificadas en la app",REACT_APP_HERO_IMAGE:"/images/mockups/hero-app.svg",REACT_APP_HERO_IMAGE_ALT:"Conversaci\xf3n con el chatbot de ReservaBot agendando una cita",REACT_APP_HERO_SUBTITLE:"Sin contestar un solo mensaje.",REACT_APP_HERO_TITLE:"Tu agenda llena",REACT_APP_HERO_TITLE_HIGHLIGHT:"24/7",REACT_APP_HERO_VISUAL:"chat",REACT_APP_INSTAGRAM_URL:"",REACT_APP_LOCATION:"Colombia \xb7 100% en la nube",REACT_APP_LOGO_HEIGHT_DESKTOP:"44",REACT_APP_LOGO_HEIGHT_MOBILE:"34",REACT_APP_LOGO_ICON_URL:"/images/brand/isotipo-reservabot.svg",REACT_APP_LOGO_URL:"/images/brand/logo-reservabot.svg",REACT_APP_NAV_LINKS:"Inicio::#hero|La app::#demos|Funciones::#features|Precio::#pricing|Preguntas::#faq",REACT_APP_PLANS_JSON:"",REACT_APP_PLAN_1_BADGE:"Primer mes GRATIS",REACT_APP_PLAN_1_DESCRIPTION:"Todo el sistema completo: chatbot de reservas, panel de administrador y app para tu equipo.",REACT_APP_PLAN_1_ENABLED:"true",REACT_APP_PLAN_1_FEATURES:"Chatbot de reservas 24/7 con tu marca|Panel de administrador: agenda, caja y reportes|App para tu equipo con su agenda del d\xeda|Colaboradores ilimitados sin costo extra|Confirmaciones y recordatorios autom\xe1ticos|Soporte y acompa\xf1amiento por WhatsApp",REACT_APP_PLAN_1_HIGHLIGHT:"true",REACT_APP_PLAN_1_NAME:"Plan ReservaBot",REACT_APP_PLAN_1_PRICE:"40000",REACT_APP_PLAN_1_PRICE_BEFORE:"",REACT_APP_PLAN_2_BADGE:"",REACT_APP_PLAN_2_DESCRIPTION:"",REACT_APP_PLAN_2_ENABLED:"false",REACT_APP_PLAN_2_FEATURES:"",REACT_APP_PLAN_2_HIGHLIGHT:"false",REACT_APP_PLAN_2_NAME:"",REACT_APP_PLAN_2_PRICE:"",REACT_APP_PLAN_2_PRICE_BEFORE:"",REACT_A